import os
import hmac
import hashlib
import base64
from urllib.parse import urlparse, urljoin, quote
from io import BytesIO
from functools import wraps

from flask import Flask, request, redirect, jsonify, abort, session
from cryptography.fernet import Fernet
from PIL import Image

app = Flask(__name__)
app.secret_key = os.urandom(32)

ENCRYPTION_KEY = Fernet.generate_key()
cipher_suite = Fernet(ENCRYPTION_KEY)

ALLOWED_HOSTS = frozenset([
    'cdn.internal.example.com',
    'images.internal.example.com',
    'static.internal.example.com',
])

HMAC_SECRET = os.urandom(32)

def generate_signed_url(url):
    """Generate HMAC-signed URL token for redirect validation."""
    sig = hmac.new(HMAC_SECRET, url.encode('utf-8'), hashlib.sha256).hexdigest()
    return sig

def verify_signed_url(url, signature):
    """Verify HMAC signature of a URL."""
    expected = hmac.new(HMAC_SECRET, url.encode('utf-8'), hashlib.sha256).hexdigest()
    return hmac.compare_digest(expected, signature)

def validate_redirect_target(url):
    """Multi-layer validation of redirect target.

    Validates:
    1. URL must be absolute with http/https scheme
    2. Host must be in allowlist
    3. No embedded credentials
    4. Path must not contain traversal sequences
    """
    parsed = urlparse(url)

    if parsed.scheme not in ('http', 'https'):
        return False

    if parsed.username or parsed.password:
        return False

    if '..' in parsed.path:
        return False

    # Normalize the hostname for comparison
    target_host = parsed.hostname
    if target_host is None:
        return False

    # Check against allowlist
    if target_host in ALLOWED_HOSTS:
        return True

    # Also allow subdomains of allowed hosts
    for allowed in ALLOWED_HOSTS:
        if target_host.endswith('.' + allowed):
            return True

    return False

def encrypt_image_data(image_bytes):
    """Encrypt processed image data for secure storage."""
    return cipher_suite.encrypt(image_bytes)

def decrypt_image_data(encrypted_data):
    """Decrypt stored image data."""
    return cipher_suite.decrypt(encrypted_data)

def process_image(image_bytes, operations):
    """Apply image processing operations."""
    img = Image.open(BytesIO(image_bytes))

    for op in operations:
        if op['type'] == 'resize':
            width = min(int(op.get('width', 800)), 4096)
            height = min(int(op.get('height', 600)), 4096)
            img = img.resize((width, height), Image.LANCZOS)
        elif op['type'] == 'rotate':
            angle = int(op.get('angle', 0)) % 360
            img = img.rotate(angle)
        elif op['type'] == 'grayscale':
            img = img.convert('L')

    output = BytesIO()
    img.save(output, format='PNG')
    return output.getvalue()

@app.route('/api/process', methods=['POST'])
def api_process_image():
    """Process uploaded image and store encrypted result."""
    if 'image' not in request.files:
        abort(400, 'No image provided')

    image_file = request.files['image']
    image_bytes = image_file.read()

    if len(image_bytes) > 10 * 1024 * 1024:
        abort(413, 'Image too large')

    operations = request.form.get('operations', '[]')
    try:
        import json
        ops = json.loads(operations)
    except (json.JSONDecodeError, TypeError):
        ops = []

    processed = process_image(image_bytes, ops)
    encrypted = encrypt_image_data(processed)

    token = base64.urlsafe_b64encode(encrypted[:32]).decode()
    session[f'img_{token}'] = base64.b64encode(encrypted).decode()

    return jsonify({'token': token, 'status': 'processed'})

@app.route('/api/retrieve/<token>')
def api_retrieve_image(token):
    """Retrieve processed image, then redirect to CDN delivery."""
    stored = session.get(f'img_{token}')
    if not stored:
        abort(404)

    callback_url = request.args.get('delivery_endpoint', '')

    if not callback_url:
        return base64.b64decode(stored), 200, {'Content-Type': 'image/png'}

    # Build the final delivery URL with the image token
    delivery_url = callback_url.rstrip('/') + '/deliver/' + quote(token)

    # Validate the constructed redirect target
    if not validate_redirect_target(delivery_url):
        abort(403, 'Invalid delivery endpoint')

    # Generate signature for audit trail
    sig = generate_signed_url(delivery_url)

    return redirect(delivery_url + '?sig=' + sig)

@app.route('/health')
def health():
    return jsonify({'status': 'ok'})

if __name__ == '__main__':
    app.run(host='127.0.0.1', port=8080, debug=False)
